 21		// ProxyConfig defines the config for Proxy middleware.
 22		ProxyConfig struct {
 23			// Skipper defines a function to skip middleware.
 24			Skipper Skipper
 25	
 26			// Balancer defines a load balancing technique.
 27			// Required.
 28			Balancer ProxyBalancer
