666	// StartTLS starts an HTTPS server.
667	// If `certFile` or `keyFile` is `string` the values are treated as file paths.
668	// If `certFile` or `keyFile` is `[]byte` the values are treated as the certificate or key as-is.
669	func (e *Echo) StartTLS(address string, certFile, keyFile interface{}) (err error) {
670		e.startupMutex.Lock()
671		var cert []byte
672		if cert, err = filepathOrContent(certFile); err != nil {
673			e.startupMutex.Unlock()
674			return
675		}
676	
677		var key []byte
678		if key, err = filepathOrContent(keyFile); err != nil {
679			e.startupMutex.Unlock()
680			return
681		}
682	
683		s := e.TLSServer
684		s.TLSConfig = new(tls.Config)
685		s.TLSConfig.Certificates = make([]tls.Certificate, 1)
686		if s.TLSConfig.Certificates[0], err = tls.X509KeyPair(cert, key); err != nil {
687			e.startupMutex.Unlock()
688			return
689		}
690	
691		e.configureTLS(address)
692		if err := e.configureServer(s); err != nil {
693			e.startupMutex.Unlock()
694			return err
695		}
696		e.startupMutex.Unlock()
697		return s.Serve(e.TLSListener)
698	}
