700	func filepathOrContent(fileOrContent interface{}) (content []byte, err error) {
701		switch v := fileOrContent.(type) {
702		case string:
703			return ioutil.ReadFile(v)
704		case []byte:
705			return v, nil
706		default:
707			return nil, ErrInvalidCertOrKeyType
708		}
709	}
