898	// WrapMiddleware wraps `func(http.Handler) http.Handler` into `echo.MiddlewareFunc`
899	func WrapMiddleware(m func(http.Handler) http.Handler) MiddlewareFunc {
900		return func(next HandlerFunc) HandlerFunc {
901			return func(c Context) (err error) {
902				m(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
903					c.SetRequest(r)
904					c.SetResponse(NewResponse(w, c.Echo()))
905					err = next(c)
906				})).ServeHTTP(c.Response(), c.Request())
907				return
