946	// tcpKeepAliveListener sets TCP keep-alive timeouts on accepted
947	// connections. It's used by ListenAndServe and ListenAndServeTLS so
948	// dead TCP connections (e.g. closing laptop mid-download) eventually
949	// go away.
950	type tcpKeepAliveListener struct {
951		*net.TCPListener
952	}
953	
954	func (ln tcpKeepAliveListener) Accept() (c net.Conn, err error) {
955		if c, err = ln.AcceptTCP(); err != nil {
956			return
957		} else if err = c.(*net.TCPConn).SetKeepAlive(true); err != nil {
958			return
959		}
960		// Ignore error from setting the KeepAlivePeriod as some systems, such as
961		// OpenBSD, do not support setting TCP_USER_TIMEOUT on IPPROTO_TCP
962		_ = c.(*net.TCPConn).SetKeepAlivePeriod(3 * time.Minute)
