2225	func (n *node) printTree(pfx string, tail bool) {
2226		p := prefix(tail, pfx, "└── ", "├── ")
2227		fmt.Printf("%s%s, %p: type=%d, parent=%p, handler=%v, pnames=%v\n", p, n.prefix, n, n.kind, n.parent, n.methodHandler, n.pnames)
2228	
2229		p = prefix(tail, pfx, "    ", "│   ")
2230	
2231		children := n.staticChildren
2232		l := len(children)
2233	
2234		if n.paramChild != nil {
2235			n.paramChild.printTree(p, n.anyChild == nil && l == 0)
2236		}
2237		if n.anyChild != nil {
2238			n.anyChild.printTree(p, l == 0)
2239		}
2240		for i := 0; i < l-1; i++ {
2241			children[i].printTree(p, false)
2242		}
2243		if l > 0 {
2244			children[l-1].printTree(p, true)
2245		}
2246	}
