 27		gzipResponseWriter struct {
 28			io.Writer
 29			http.ResponseWriter
 30		}
 31	)
 32	
 33	const (
 34		gzipScheme = "gzip"
 35	)
 36	
 37	var (
 38		// DefaultGzipConfig is the default Gzip middleware config.
 39		DefaultGzipConfig = GzipConfig{
 40			Skipper: DefaultSkipper,
 41			Level:   -1,
 42		}
 43	)
 44	
 45	// Gzip returns a middleware which compresses HTTP response using gzip compression
 46	// scheme.
 47	func Gzip() echo.MiddlewareFunc {
 48		return GzipWithConfig(DefaultGzipConfig)
 49	}
 50	
 51	// GzipWithConfig return Gzip middleware with config.
 52	// See: `Gzip()`.
 53	func GzipWithConfig(config GzipConfig) echo.MiddlewareFunc {
 54		// Defaults
 55		if config.Skipper == nil {
 56			config.Skipper = DefaultGzipConfig.Skipper
 57		}
 58		if config.Level == 0 {
 59			config.Level = DefaultGzipConfig.Level
 60		}
 61	
 62		pool := gzipCompressPool(config)
 63	
 64		return func(next echo.HandlerFunc) echo.HandlerFunc {
 65			return func(c echo.Context) error {
 66				if config.Skipper(c) {
 67					return next(c)
 68				}
 69	
 70				res := c.Response()
 71				res.Header().Add(echo.HeaderVary, echo.HeaderAcceptEncoding)
 72				if strings.Contains(c.Request().Header.Get(echo.HeaderAcceptEncoding), gzipScheme) {
 73					res.Header().Set(echo.HeaderContentEncoding, gzipScheme) // Issue #806
 74					i := pool.Get()
 75					w, ok := i.(*gzip.Writer)
 76					if !ok {
 77						return echo.NewHTTPError(http.StatusInternalServerError, i.(error).Error())
 78					}
 79					rw := res.Writer
 80					w.Reset(rw)
 81					defer func() {
 82						if res.Size == 0 {
 83							if res.Header().Get(echo.HeaderContentEncoding) == gzipScheme {
 84								res.Header().Del(echo.HeaderContentEncoding)
 85							}
 86							// We have to reset response to it's pristine state when
 87							// nothing is written to body or error is returned.
 88							// See issue #424, #407.
 89							res.Writer = rw
 90							w.Reset(ioutil.Discard)
 91						}
 92						w.Close()
 93						pool.Put(w)
 94					}()
 95					grw := &gzipResponseWriter{Writer: w, ResponseWriter: rw}
 96					res.Writer = grw
 97				}
 98				return next(c)
 99			}
100		}
101	}
