103	func (w *gzipResponseWriter) WriteHeader(code int) {
104		if code == http.StatusNoContent { // Issue #489
105			w.ResponseWriter.Header().Del(echo.HeaderContentEncoding)
106		}
107		w.Header().Del(echo.HeaderContentLength) // Issue #444
108		w.ResponseWriter.WriteHeader(code)
109	}
110	
111	func (w *gzipResponseWriter) Write(b []byte) (int, error) {
112		if w.Header().Get(echo.HeaderContentType) == "" {
113			w.Header().Set(echo.HeaderContentType, http.DetectContentType(b))
114		}
115		return w.Writer.Write(b)
116	}
117	
118	func (w *gzipResponseWriter) Flush() {
119		w.Writer.(*gzip.Writer).Flush()
120		if flusher, ok := w.ResponseWriter.(http.Flusher); ok {
121			flusher.Flush()
122		}
123	}
124	
125	func (w *gzipResponseWriter) Hijack() (net.Conn, *bufio.ReadWriter, error) {
126		return w.ResponseWriter.(http.Hijacker).Hijack()
127	}
128	
129	func (w *gzipResponseWriter) Push(target string, opts *http.PushOptions) error {
130		if p, ok := w.ResponseWriter.(http.Pusher); ok {
131			return p.Push(target, opts)
132		}
133		return http.ErrNotSupported
134	}
135	
136	func gzipCompressPool(config GzipConfig) sync.Pool {
137		return sync.Pool{
138			New: func() interface{} {
139				w, err := gzip.NewWriterLevel(ioutil.Discard, config.Level)
140				if err != nil {
141					return err
142				}
143				return w
144			},
145		}
146	}

