func TestZZSchemeTmp(t *testing.T) {
	newCtx := func() *context {
		e := New()
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		return e.NewContext(req, nil).(*context)
	}

	// (a) X-Forwarded-Proto invalid + X-Forwarded-Protocol=https -> https
	c := newCtx()
	c.request.Header.Set(HeaderXForwardedProto, "invalid")
	c.request.Header.Set(HeaderXForwardedProtocol, "https")
	if got := c.Scheme(); got != "https" {
		t.Errorf("(a) got %q, want https", got)
	}

	// (b) all four headers invalid -> http
	c = newCtx()
	c.request.Header.Set(HeaderXForwardedProto, "invalid")
	c.request.Header.Set(HeaderXForwardedProtocol, "ftp")
	c.request.Header.Set(HeaderXForwardedSsl, "off")
	c.request.Header.Set(HeaderXUrlScheme, "javascript")
	if got := c.Scheme(); got != "http" {
		t.Errorf("(b) got %q, want http", got)
	}

	// (c) X-Forwarded-Proto=https -> https
	c = newCtx()
	c.request.Header.Set(HeaderXForwardedProto, "https")
	if got := c.Scheme(); got != "https" {
		t.Errorf("(c) got %q, want https", got)
	}

	// (d) X-Forwarded-Ssl=on -> https
	c = newCtx()
	c.request.Header.Set(HeaderXForwardedSsl, "on")
	if got := c.Scheme(); got != "https" {
		t.Errorf("(d) got %q, want https", got)
	}

	// (e) X-Url-Scheme=https -> https
	c = newCtx()
	c.request.Header.Set(HeaderXUrlScheme, "https")
	if got := c.Scheme(); got != "https" {
		t.Errorf("(e) got %q, want https", got)
	}

	// (f) TLS -> https
	c = newCtx()
	c.request.TLS = &tls.ConnectionState{}
	if got := c.Scheme(); got != "https" {
		t.Errorf("(f) got %q, want https", got)
	}

	// extra: case-insensitive acceptance returns original value
	c = newCtx()
	c.request.Header.Set(HeaderXForwardedProto, "HTTPS")
	if got := c.Scheme(); got != "HTTPS" {
		t.Errorf("(g) got %q, want HTTPS", got)
	}
}

